using System.Data;
using System.Globalization;
using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Xml.Linq;
using DotNet.Testcontainers.Configurations;
using FluentAssertions;
using Microsoft.Data.SqlClient;
using Testcontainers.MsSql;

#pragma warning disable CA2100 // Every dynamic identifier is generated by this isolated test.

namespace HVO.SkyMonitor.IntegrationTests;

[TestClass]
[TestCategory("Integration")]
[DoNotParallelize]
public sealed class SqlOperationsIssue255Tests
{
    private static readonly string Password = $"Issue255_{Guid.NewGuid():N}_aA1!";
    private const string ApprovedDirectory = "/var/opt/mssql/data";
    private const string EventRootDirectory = "/var/opt/mssql/data/issue255-xe-root";
    private const string BackupFilePrefix = "hvo255_backup_";
    private const string MetadataRetentionControlReference = "issue255-test-manual-control";
    private const int MetadataRetentionDeclaredDays = 30;

    [TestMethod]
    [Timeout(240_000)]
    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1031:Do not catch general exception types",
        Justification = "The MSTest boundary must discard all raw setup, SQL, assertion, and cleanup exception details.")]
    public async Task OperatorToolkit_ProducesSanitizedEvidenceAndExactCleanup()
    {
        var stage = new SafeStage("container-start");
        try
        {
            await RunOperatorToolkitAsync(stage).ConfigureAwait(false);
        }
        catch (Exception exception)
        {
            var errorNumber = exception is SanitizedScriptException sanitized ? sanitized.SqlErrorNumber : 0;
            throw new AssertFailedException($"Issue 255 sanitized stage '{stage.Value}' failed with bounded error {errorNumber}.");
        }
    }

    private static async Task RunOperatorToolkitAsync(SafeStage stage)
    {
        var startedAt = DateTimeOffset.UtcNow;
        var runId = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
        var queryStoreToken = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
        var databaseName = $"Issue255_{runId}";
        var instanceLogin = $"Issue255InstanceOperator_{runId}";
        var databaseLogin = $"Issue255DatabaseOperator_{runId}";
        var recoveryLogin = $"Issue255Recovery_{runId}";
        var runtimeLogin = $"Issue255Runtime_{runId}";
        var migrationLogin = $"Issue255Migration_{runId}";
        var canaryLiteral = $"issue255-literal-{runId}";
        var canaryParameter = $"issue255-parameter-{runId}";
        var eventRunDirectory = $"{EventRootDirectory}/hvo-xe-{runId}";
        var eventFilePath = $"{eventRunDirectory}/events";
        var backupFilePath = $"{ApprovedDirectory}/{BackupFilePrefix}{runId}.bak";
        var sessionName = $"HvoSqlOps_{runId}";
        var allSanitizedOutput = new List<string>();
        var permissionEvidence = new List<PermissionEvidence>();
        var originalBlockedThreshold = 0;
        var originalShowAdvanced = 0;

        await using var container = new MsSqlBuilder()
            .WithImage(IntegrationTestFixture.SqlServerImage)
            .WithPassword(Password)
            .WithEnvironment("ISSUE255_SQLCMD_USER", instanceLogin)
            .WithEnvironment("HVO_SQL_XE_ENABLE_TEST_FAULTS", "1")
            .Build();
        await container.StartAsync().ConfigureAwait(false);
        var adminConnectionString = container.GetConnectionString();
        try
        {
            stage.Value = "isolated-setup";
            await using (var admin = await OpenAsync(adminConnectionString, "master").ConfigureAwait(false))
            {
                originalBlockedThreshold = await ScalarAsync<int>(admin,
                    "SELECT CONVERT(int, [value_in_use]) FROM sys.configurations WHERE [name]=N'blocked process threshold (s)';")
                    .ConfigureAwait(false);
                originalShowAdvanced = await ScalarAsync<int>(admin,
                    "SELECT CONVERT(int, [value_in_use]) FROM sys.configurations WHERE [name]=N'show advanced options';")
                    .ConfigureAwait(false);
                await NonQueryAsync(admin, $"""
                    CREATE DATABASE [{databaseName}];
                    ALTER DATABASE [{databaseName}] SET COMPATIBILITY_LEVEL = 160;
                    CREATE LOGIN [{instanceLogin}] WITH PASSWORD=N'{Password}';
                    GRANT VIEW SERVER PERFORMANCE STATE TO [{instanceLogin}];
                    CREATE LOGIN [{databaseLogin}] WITH PASSWORD=N'{Password}';
                    CREATE LOGIN [{recoveryLogin}] WITH PASSWORD=N'{Password}';
                    ALTER SERVER ROLE [sysadmin] ADD MEMBER [{recoveryLogin}];
                    CREATE LOGIN [{runtimeLogin}] WITH PASSWORD=N'{Password}';
                    CREATE LOGIN [{migrationLogin}] WITH PASSWORD=N'{Password}';
                    EXEC sys.sp_configure N'show advanced options', 1;
                    RECONFIGURE;
                    EXEC sys.sp_configure N'blocked process threshold (s)', 5;
                    RECONFIGURE;
                    """).ConfigureAwait(false);
            }
            await using (var database = await OpenAsync(adminConnectionString, databaseName).ConfigureAwait(false))
            {
                await NonQueryAsync(database, $"""
                    CREATE TABLE dbo.Issue255Invariant (
                        Id int NOT NULL CONSTRAINT PK_Issue255Invariant PRIMARY KEY,
                        Payload nvarchar(200) NOT NULL,
                        Quantity int NOT NULL);
                    INSERT dbo.Issue255Invariant (Id, Payload, Quantity)
                    VALUES (1, N'{canaryLiteral}', 11), (2, N'{canaryParameter}', 22);
                    CREATE TABLE dbo.Issue255DuplicateInvariant (Id int NOT NULL, Payload nvarchar(200) NOT NULL, Quantity int NOT NULL);
                    INSERT dbo.Issue255DuplicateInvariant (Id, Payload, Quantity) VALUES (1, N'a', 1), (1, N'b', 2);
                    CREATE TABLE dbo.Issue255NullInvariant (Id int NULL, Payload nvarchar(200) NOT NULL, Quantity int NOT NULL);
                    CREATE UNIQUE INDEX UX_Issue255NullInvariant_Id ON dbo.Issue255NullInvariant(Id);
                    INSERT dbo.Issue255NullInvariant (Id, Payload, Quantity) VALUES (NULL, N'a', 1);
                    CREATE TABLE dbo.Issue255DisabledInvariant (Id int NOT NULL, Payload nvarchar(200) NOT NULL, Quantity int NOT NULL);
                    CREATE UNIQUE INDEX UX_Issue255DisabledInvariant_Id ON dbo.Issue255DisabledInvariant(Id);
                    INSERT dbo.Issue255DisabledInvariant (Id, Payload, Quantity) VALUES (1, N'a', 1);
                    ALTER INDEX UX_Issue255DisabledInvariant_Id ON dbo.Issue255DisabledInvariant DISABLE;
                    CREATE TABLE dbo.Issue255FilteredInvariant (Id int NOT NULL, Payload nvarchar(200) NOT NULL, Quantity int NOT NULL);
                    CREATE UNIQUE INDEX UX_Issue255FilteredInvariant_Id ON dbo.Issue255FilteredInvariant(Id) WHERE Id > 0;
                    INSERT dbo.Issue255FilteredInvariant (Id, Payload, Quantity) VALUES (1, N'a', 1);
                    CREATE TABLE dbo.__EFMigrationsHistory (MigrationId nvarchar(150) NOT NULL PRIMARY KEY, ProductVersion nvarchar(32) NOT NULL);
                    CREATE TABLE dbo.DatabaseInitializationState (Id int NOT NULL PRIMARY KEY, Status nvarchar(32) NOT NULL);
                    INSERT dbo.DatabaseInitializationState (Id, Status) VALUES (1, N'Completed');
                    CREATE USER [{databaseLogin}] FOR LOGIN [{databaseLogin}];
                    GRANT VIEW DATABASE PERFORMANCE STATE TO [{databaseLogin}];
                    GRANT VIEW PERFORMANCE DEFINITION TO [{databaseLogin}];
                    CREATE USER [{instanceLogin}] FOR LOGIN [{instanceLogin}];
                    GRANT CONNECT TO [{instanceLogin}];
                    GRANT VIEW DATABASE PERFORMANCE STATE TO [{instanceLogin}];
                    GRANT VIEW PERFORMANCE DEFINITION TO [{instanceLogin}];
                    GRANT REFERENCES ON SCHEMA::dbo TO [{instanceLogin}];
                    CREATE USER [{runtimeLogin}] FOR LOGIN [{runtimeLogin}];
                    CREATE USER [{migrationLogin}] FOR LOGIN [{migrationLogin}];
                    """).ConfigureAwait(false);
                _ = await ExecuteScriptAsync(database, "logichost-runtime-role.sql",
                    new Dictionary<string, string> { ["DatabaseName"] = databaseName, ["RuntimeUser"] = runtimeLogin }).ConfigureAwait(false);
                _ = await ExecuteScriptAsync(database, "logichost-migration-role.sql",
                    new Dictionary<string, string> { ["DatabaseName"] = databaseName, ["MigrationUser"] = migrationLogin }).ConfigureAwait(false);
            }

            var instanceConnectionString = CreatePrincipalConnectionString(adminConnectionString, instanceLogin);
            var databaseConnectionString = CreatePrincipalConnectionString(adminConnectionString, databaseLogin);
            var recoveryConnectionString = CreatePrincipalConnectionString(adminConnectionString, recoveryLogin);
            stage.Value = "real-sqlcmd-adversarial";
            await AssertRealSqlCmdEscapingAsync(container, adminConnectionString, runId).ConfigureAwait(false);
            await using (var serverOperator = await OpenAsync(instanceConnectionString, "master").ConfigureAwait(false))
            {
                await RecordPermissionAsync(serverOperator, permissionEvidence, "VIEW SERVER PERFORMANCE STATE", true).ConfigureAwait(false);
                await RecordPermissionAsync(serverOperator, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
                await RecordPermissionAsync(serverOperator, permissionEvidence, "ALTER TRACE", false).ConfigureAwait(false);
                await RecordPermissionAsync(serverOperator, permissionEvidence, "ALTER SETTINGS", false).ConfigureAwait(false);
                await RecordPermissionAsync(serverOperator, permissionEvidence, "CONTROL SERVER", false).ConfigureAwait(false);
            }
            await using (var databaseServer = await OpenAsync(databaseConnectionString, "master").ConfigureAwait(false))
            {
                await RecordPermissionAsync(databaseServer, permissionEvidence, "VIEW SERVER PERFORMANCE STATE", false).ConfigureAwait(false);
                await RecordPermissionAsync(databaseServer, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
            }
            await using var databaseOperator = await OpenAsync(databaseConnectionString, databaseName).ConfigureAwait(false);
            await RecordPermissionAsync(databaseOperator, permissionEvidence, "ALTER", false, "DATABASE").ConfigureAwait(false);
            await RecordPermissionAsync(databaseOperator, permissionEvidence, "VIEW DATABASE PERFORMANCE STATE", true, "DATABASE").ConfigureAwait(false);
            await RecordPermissionAsync(databaseOperator, permissionEvidence, "VIEW PERFORMANCE DEFINITION", true, "DATABASE").ConfigureAwait(false);
            await RecordPermissionAsync(databaseOperator, permissionEvidence, "VIEW SECURITY DEFINITION", false, "DATABASE").ConfigureAwait(false);
            await using (var recoveryServer = await OpenAsync(recoveryConnectionString, "master").ConfigureAwait(false))
                await RecordServerRoleMembershipAsync(recoveryServer, permissionEvidence, "sysadmin").ConfigureAwait(false);
            foreach (var applicationLogin in new[] { runtimeLogin, migrationLogin })
            {
                var applicationConnection = CreatePrincipalConnectionString(adminConnectionString, applicationLogin);
                await using var applicationServer = await OpenAsync(applicationConnection, "master").ConfigureAwait(false);
                await RecordPermissionAsync(applicationServer, permissionEvidence, "VIEW SERVER PERFORMANCE STATE", false).ConfigureAwait(false);
                await RecordPermissionAsync(applicationServer, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
                await using var applicationDatabase = await OpenAsync(applicationConnection, databaseName).ConfigureAwait(false);
                await RecordPermissionAsync(applicationDatabase, permissionEvidence, "VIEW DATABASE PERFORMANCE STATE", false, "DATABASE").ConfigureAwait(false);
                await RecordPermissionAsync(applicationDatabase, permissionEvidence, "BACKUP DATABASE", false, "DATABASE").ConfigureAwait(false);
                await RecordPermissionAsync(applicationDatabase, permissionEvidence, "ALTER", false, "DATABASE").ConfigureAwait(false);
            }

            stage.Value = "query-store";
            var baselineResult = await ExecuteScriptAsync(databaseOperator, "query-store-capture.sql",
                new Dictionary<string, string> { ["DatabaseName"] = databaseName }).ConfigureAwait(false);
            var baseline = RequireSingleRow(baselineResult, 0,
                "area", "desired_state", "actual_state", "readonly_reason", "maximum_storage_mb", "retention_days",
                "interval_minutes", "maximum_plans_per_query", "flush_seconds", "capture_mode", "cleanup_mode", "wait_stats_mode");
            RequireText(baseline, "area").Should().Be("query-store-baseline");
            RequireText(baseline, "desired_state").Should().BeOneOf("OFF", "READ_ONLY", "READ_WRITE");
            RequireText(baseline, "actual_state").Should().BeOneOf("OFF", "READ_ONLY", "READ_WRITE");
            AddOutput(allSanitizedOutput, baselineResult);

            var queryStoreVariables = QueryStoreConfigureVariables(databaseName, queryStoreToken, baseline);
            var noElevationFailure = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", queryStoreVariables)).ConfigureAwait(false);
            noElevationFailure.SqlErrorNumber.Should().Be(51301);
            (await QueryStoreOwnerCountAsync(databaseOperator).ConfigureAwait(false)).Should().Be(0);
            await SetDatabaseAlterAsync(adminConnectionString, databaseName, databaseLogin, grant: true).ConfigureAwait(false);
            await RecordPermissionAsync(databaseOperator, permissionEvidence, "ALTER", true, "DATABASE").ConfigureAwait(false);

            var invalidVariables = new Dictionary<string, string>(queryStoreVariables, StringComparer.Ordinal) { ["MaxStorageMb"] = "not-an-integer" };
            var invalidConfiguration = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", invalidVariables)).ConfigureAwait(false);
            AssertFailureIsSanitized(invalidConfiguration, canaryLiteral, eventFilePath, backupFilePath, Password);
            (await QueryStoreOwnerCountAsync(databaseOperator).ConfigureAwait(false)).Should().Be(0);

            var staleOwner = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
            await NonQueryAsync(databaseOperator,
                $"EXEC sys.sp_addextendedproperty @name=N'HvoSqlOps_QueryStoreOwner', @value='{staleOwner}';").ConfigureAwait(false);
            _ = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", queryStoreVariables)).ConfigureAwait(false);
            _ = await CaptureSanitizedScriptFailureAsync(() => ExecuteScriptAsync(databaseOperator,
                "query-store-capture.sql", new Dictionary<string, string> { ["DatabaseName"] = databaseName })).ConfigureAwait(false);
            await NonQueryAsync(databaseOperator,
                "EXEC sys.sp_dropextendedproperty @name=N'HvoSqlOps_QueryStoreOwner';").ConfigureAwait(false);

            var mismatchVariables = new Dictionary<string, string>(queryStoreVariables, StringComparer.Ordinal)
            {
                ["OriginalDesiredState"] = "READ_WRITE",
                ["OriginalActualState"] = "READ_ONLY",
                ["OriginalReadonlyReason"] = "1"
            };
            _ = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", mismatchVariables)).ConfigureAwait(false);

            await NonQueryAsync(databaseOperator, "ALTER DATABASE CURRENT SET QUERY_STORE (MAX_STORAGE_SIZE_MB=200);").ConfigureAwait(false);
            _ = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", queryStoreVariables)).ConfigureAwait(false);
            (await QueryStoreOwnerCountAsync(databaseOperator).ConfigureAwait(false)).Should().Be(0);
            await NonQueryAsync(databaseOperator,
                $"ALTER DATABASE CURRENT SET QUERY_STORE (MAX_STORAGE_SIZE_MB={RequireInt64(baseline, "maximum_storage_mb")});").ConfigureAwait(false);

            var configureResult = await ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", queryStoreVariables).ConfigureAwait(false);
            await SetDatabaseAlterAsync(adminConnectionString, databaseName, databaseLogin, grant: false).ConfigureAwait(false);
            await RecordPermissionAsync(databaseOperator, permissionEvidence, "ALTER", false, "DATABASE").ConfigureAwait(false);
            var configured = RequireSingleRow(configureResult, 0,
                "area", "ownership_state", "desired_state", "actual_state", "readonly_reason", "current_storage_mb", "maximum_storage_mb",
                "retention_days", "interval_minutes", "maximum_plans_per_query");
            RequireText(configured, "area").Should().Be("query-store");
            RequireText(configured, "ownership_state").Should().Be("acquired");
            RequireText(configured, "desired_state").Should().Be("READ_WRITE");
            RequireText(configured, "actual_state").Should().Be("READ_WRITE");
            RequireInt64(configured, "readonly_reason").Should().Be(0);
            AddOutput(allSanitizedOutput, configureResult);
            var concurrentVariables = new Dictionary<string, string>(queryStoreVariables, StringComparer.Ordinal)
            {
                ["QueryStoreToken"] = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture)
            };
            _ = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(databaseOperator, "query-store-configure.sql", concurrentVariables)).ConfigureAwait(false);
            (await QueryStoreOwnerCountAsync(databaseOperator, queryStoreToken).ConfigureAwait(false)).Should().Be(1);

            await using (var canaryConnection = await OpenAsync(adminConnectionString, databaseName).ConfigureAwait(false))
            {
                await NonQueryAsync(canaryConnection, "ALTER DATABASE CURRENT SET QUERY_STORE (QUERY_CAPTURE_MODE=ALL);").ConfigureAwait(false);
                for (var index = 0; index < 8; index++)
                {
                    await using var canary = canaryConnection.CreateCommand();
                    canary.CommandText = $"SELECT COUNT(*) FROM dbo.Issue255Invariant WHERE Payload=N'{canaryLiteral}' OR Payload=@payload;";
                    _ = canary.Parameters.Add(new SqlParameter("@payload", SqlDbType.NVarChar, 200) { Value = canaryParameter });
                    _ = await canary.ExecuteScalarAsync().ConfigureAwait(false);
                }
                await NonQueryAsync(canaryConnection, "EXEC sys.sp_query_store_flush_db;").ConfigureAwait(false);
                await NonQueryAsync(canaryConnection, "ALTER DATABASE CURRENT SET QUERY_STORE (QUERY_CAPTURE_MODE=AUTO);").ConfigureAwait(false);
            }
            var canaryObserved = (await ReadStringsAsync(databaseOperator, """
                SELECT texts.[query_sql_text] FROM sys.query_store_query_text AS texts
                WHERE texts.[query_sql_text] LIKE N'%issue255%';
                """).ConfigureAwait(false)).Any(text => text.Contains(canaryLiteral, StringComparison.Ordinal));
            if (!canaryObserved) Assert.Fail("The restricted in-memory Query Store canary was not observed.");

            var inspectResult = await ExecuteScriptAsync(databaseOperator, "query-store-inspect.sql",
                new Dictionary<string, string>
                {
                    ["DatabaseName"] = databaseName,
                    ["QueryStoreToken"] = queryStoreToken,
                    ["WindowMinutes"] = "60"
                }).ConfigureAwait(false);
            var queryMetrics = RequireSingleRow(inspectResult, 0,
                "area", "window_start_utc", "window_end_utc", "query_count", "plan_count", "execution_count",
                "weighted_duration_microseconds", "weighted_cpu_microseconds", "weighted_logical_reads",
                "weighted_logical_writes", "maximum_plan_variation");
            RequireInt64(queryMetrics, "query_count").Should().BePositive();
            RequireInt64(queryMetrics, "plan_count").Should().BePositive();
            RequireInt64(queryMetrics, "execution_count").Should().BePositive();
            RequireDecimal(queryMetrics, "weighted_duration_microseconds").Should().BePositive();
            RequireDecimal(queryMetrics, "weighted_cpu_microseconds").Should().BePositive();
            RequireDecimal(queryMetrics, "weighted_logical_reads").Should().BePositive();
            AddOutput(allSanitizedOutput, inspectResult);

            stage.Value = "extended-events";
            var createEventRoot = await container.ExecAsync([
                "install", "-d", "-m", "0750", "-o", "mssql", "-g", "mssql", "--", EventRootDirectory
            ]).ConfigureAwait(false);
            createEventRoot.ExitCode.Should().Be(0);
            await InstallXeWrapperAsync(container).ConfigureAwait(false);
            stage.Value = "xe-wrapper-traversal-execution";
            var traversalAccepted = await RunXeWrapperPreflightAsync(container, "../not-a-run").ConfigureAwait(false);
            stage.Value = "xe-wrapper-traversal-result";
            traversalAccepted.Should().BeFalse();
            stage.Value = "xe-invalid-instance-wide-selection";
            await using var serverOperatorForXe = await OpenAsync(instanceConnectionString, "master").ConfigureAwait(false);
            foreach (var fault in new[] { "post-sql-parse", "postcheck-ownership" })
            {
                var faultRun = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
                stage.Value = $"xe-wrapper-production-{fault}";
                await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: true).ConfigureAwait(false);
                XeWrapperResult faultResult;
                try
                {
                    await RecordPermissionAsync(serverOperatorForXe, permissionEvidence, "ALTER ANY EVENT SESSION", true).ConfigureAwait(false);
                    faultResult = await RunXeWrapperProductionAsync(container, databaseName, faultRun, fault).ConfigureAwait(false);
                }
                finally
                {
                    await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: false).ConfigureAwait(false);
                }
                await RecordPermissionAsync(serverOperatorForXe, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
                faultResult.ExitCode.Should().Be(1);
                faultResult.StandardOutput.Should().BeEmpty();
                faultResult.StandardError.Should().EndWith("XE creation failed; exact session and run-directory cleanup completed.");
                AssertForbiddenValuesAbsent([faultResult.StandardOutput, faultResult.StandardError],
                    faultRun, databaseName, EventRootDirectory, Password);
                (await ScalarAsync<int>(serverOperatorForXe,
                    $"SELECT COUNT(*) FROM sys.server_event_sessions WHERE [name]=N'HvoSqlOps_{faultRun}';").ConfigureAwait(false)).Should().Be(0);
                var faultDirectory = await container.ExecAsync([
                    "/bin/sh", "-c", $"test ! -e '{EventRootDirectory}/hvo-xe-{faultRun}'"
                ]).ConfigureAwait(false);
                faultDirectory.ExitCode.Should().Be(0);
            }

            var invalidXeRun = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
            var invalidXeDirectory = $"{EventRootDirectory}/hvo-xe-{invalidXeRun}";
            var invalidXeVariables = XeVariables(databaseName, invalidXeRun, invalidXeDirectory,
                $"{invalidXeDirectory}/events", includeInstanceWideDeadlocks: "0");
            var invalidXe = await CaptureSanitizedScriptFailureAsync(
                () => ExecuteScriptAsync(serverOperatorForXe, "xe-create.sql", invalidXeVariables)).ConfigureAwait(false);
            AssertFailureIsSanitized(invalidXe, canaryLiteral, eventFilePath, backupFilePath, Password);
            (await ScalarAsync<int>(serverOperatorForXe,
                $"SELECT COUNT(*) FROM sys.server_event_sessions WHERE [name]=N'HvoSqlOps_{invalidXeRun}';").ConfigureAwait(false)).Should().Be(0);

            var invalidXePathRun = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
            stage.Value = "xe-invalid-path";
            var invalidXeDirectoryPath = $"/var/tmp/../hvo-xe-{invalidXePathRun}";
            var invalidXePath = $"{invalidXeDirectoryPath}/events";
            var invalidPathXe = await CaptureSanitizedScriptFailureAsync(() => ExecuteScriptAsync(
                serverOperatorForXe,
                "xe-create.sql",
                XeVariables(databaseName, invalidXePathRun, invalidXeDirectoryPath, invalidXePath, "1"))).ConfigureAwait(false);
            AssertFailureIsSanitized(invalidPathXe, invalidXePathRun, invalidXePath, Password);
            (await ScalarAsync<int>(serverOperatorForXe,
                $"SELECT COUNT(*) FROM sys.server_event_sessions WHERE [name]=N'HvoSqlOps_{invalidXePathRun}';").ConfigureAwait(false)).Should().Be(0);

            var noncanonicalRun = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
            stage.Value = "xe-noncanonical-path";
            var noncanonicalRoot = "/var/opt//mssql/data";
            var noncanonicalDirectory = $"{noncanonicalRoot}/hvo-xe-{noncanonicalRun}";
            _ = await CaptureSanitizedScriptFailureAsync(() => ExecuteScriptAsync(serverOperatorForXe, "xe-create.sql",
                XeVariables(databaseName, noncanonicalRun, noncanonicalDirectory, $"{noncanonicalDirectory}/events", "1"))).ConfigureAwait(false);

            var failedStartRun = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
            stage.Value = "xe-failed-start-cleanup";
            var missingDirectory = $"/root/hvo-xe-{failedStartRun}";
            var failedStartPath = $"{missingDirectory}/events";
            await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: true).ConfigureAwait(false);
            SanitizedScriptException failedStartXe;
            try
            {
                failedStartXe = await CaptureSanitizedScriptFailureAsync(() => ExecuteScriptAsync(
                    serverOperatorForXe,
                    "xe-create.sql",
                    XeVariables(databaseName, failedStartRun, missingDirectory, failedStartPath, "1"))).ConfigureAwait(false);
            }
            finally
            {
                await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: false).ConfigureAwait(false);
            }
            await RecordPermissionAsync(serverOperatorForXe, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
            AssertFailureIsSanitized(failedStartXe, failedStartRun, missingDirectory, failedStartPath, Password);
            (await ScalarAsync<int>(serverOperatorForXe,
                $"SELECT COUNT(*) FROM sys.server_event_sessions WHERE [name]=N'HvoSqlOps_{failedStartRun}';").ConfigureAwait(false)).Should().Be(0);

            var replacedTargetRun = Guid.NewGuid().ToString("N", CultureInfo.InvariantCulture);
            stage.Value = "xe-wrapper-replaced-target-preflight";
            var replacedTargetDirectory = $"{EventRootDirectory}/hvo-xe-{replacedTargetRun}";
            var replacedTargetPath = $"{replacedTargetDirectory}/events";
            (await RunXeWrapperPreflightAsync(container, replacedTargetRun, stage).ConfigureAwait(false)).Should().BeTrue();
            await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: true).ConfigureAwait(false);
            try
            {
                _ = await ExecuteScriptAsync(serverOperatorForXe, "xe-create.sql",
                    XeVariables(databaseName, replacedTargetRun, replacedTargetDirectory, replacedTargetPath, "1")).ConfigureAwait(false);
                _ = await ExecuteScriptAsync(serverOperatorForXe, "xe-drop.sql",
                    new Dictionary<string, string> { ["RunId"] = replacedTargetRun }).ConfigureAwait(false);
            }
            finally
            {
                await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: false).ConfigureAwait(false);
            }
            await RecordPermissionAsync(serverOperatorForXe, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
            await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: true).ConfigureAwait(false);
            try
            {
                await NonQueryAsync(serverOperatorForXe, $"""
                    CREATE EVENT SESSION [HvoSqlOps_{replacedTargetRun}] ON SERVER
                    ADD EVENT sqlserver.xml_deadlock_report
                    ADD TARGET package0.event_file(SET filename=N'{replacedTargetPath}_replaced', max_file_size=(5), max_rollover_files=(2))
                    WITH (STARTUP_STATE=OFF);
                    """).ConfigureAwait(false);
            }
            finally
            {
                await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: false).ConfigureAwait(false);
            }
            _ = await CaptureSanitizedScriptFailureAsync(() => ExecuteScriptAsync(serverOperatorForXe,
                "xe-read-sanitized.sql", XeReadVariables(replacedTargetRun, replacedTargetPath))).ConfigureAwait(false);
            await RecordPermissionAsync(serverOperatorForXe, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
            await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: true).ConfigureAwait(false);
            try
            {
