            sanitizedEvents.Any(item => item.EventKind == "blocked-process").Should().BeTrue();
            sanitizedEvents.Any(item => item.EventKind == "blocked-process" && item.ParticipantSet == "logichost-runtime").Should().BeTrue();
            sanitizedEvents.Any(item => item.EventKind == "deadlock" && item.Attribution == "mixed-approved" &&
