            await RecordPermissionAsync(databaseOperator, permissionEvidence, "ALTER", true, "DATABASE").ConfigureAwait(false);
            var wrongOwnerRollback = new Dictionary<string, string>(rollbackVariables, StringComparer.Ordinal)
            {
