            var rollbackResult = await ExecuteScriptAsync(databaseOperator, "query-store-rollback.sql", rollbackVariables).ConfigureAwait(false);
            await SetDatabaseAlterAsync(adminConnectionString, databaseName, databaseLogin, grant: false).ConfigureAwait(false);
