            await NonQueryAsync(customAdmin,
                "ALTER DATABASE CURRENT SET QUERY_STORE (QUERY_CAPTURE_MODE=AUTO); ALTER DATABASE CURRENT SET QUERY_STORE = OFF;").ConfigureAwait(false);

            await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: true).ConfigureAwait(false);
            ScriptResult xeDropResult;
            try
            {
