                await SetServerPermissionAsync(adminConnectionString, instanceLogin, "ALTER ANY EVENT SESSION", grant: false).ConfigureAwait(false);
            }
            await RecordPermissionAsync(serverOperatorForXe, permissionEvidence, "ALTER ANY EVENT SESSION", false).ConfigureAwait(false);
            var dropped = RequireSingleRow(xeDropResult, 0, "area", "state");
            RequireText(dropped, "state").Should().Be("dropped");
            AddOutput(allSanitizedOutput, xeDropResult);
            await DeleteExactFilesAsync(container, eventFilePath, backupFilePath).ConfigureAwait(false);
            await using (var metadataAdmin = await OpenAsync(adminConnectionString, "msdb").ConfigureAwait(false))
            {
                (await ScalarAsync<int>(metadataAdmin,
                    $"SELECT COUNT(*) FROM dbo.backupset WHERE [name]=N'HvoSqlOps_{runId}' AND [type]=N'D' AND [is_copy_only]=1;").ConfigureAwait(false)).Should().Be(1);
                await NonQueryAsync(metadataAdmin,
                    $"EXEC dbo.sp_delete_database_backuphistory @database_name=N'{databaseName}';").ConfigureAwait(false);
                (await ScalarAsync<int>(metadataAdmin,
                    $"SELECT COUNT(*) FROM dbo.backupset WHERE [database_name]=N'{databaseName}';").ConfigureAwait(false)).Should().Be(0);
                (await ScalarAsync<int>(metadataAdmin,
                    $"SELECT COUNT(*) FROM dbo.backupmediafamily WHERE [physical_device_name]=N'{backupFilePath}';").ConfigureAwait(false)).Should().Be(0);
                (await ScalarAsync<int>(metadataAdmin,
                    $"SELECT COUNT(*) FROM dbo.backupmediaset WHERE [name]=N'HvoSqlOpsMedia_{runId}';").ConfigureAwait(false)).Should().Be(0);
            }
            await AssertExactCleanupAsync(adminConnectionString, container, databaseName, sessionName, eventFilePath, backupFilePath).ConfigureAwait(false);

            AssertForbiddenValuesAbsent(allSanitizedOutput,
                canaryLiteral, canaryParameter, runId, databaseName, instanceLogin, databaseLogin, recoveryLogin, runtimeLogin, migrationLogin,
                eventFilePath, backupFilePath, EventRootDirectory, ApprovedDirectory, Password,
                "query_sql_text", "statement", "showplan", "deadlock/resource-list", "blocked-process-report");
            AssertApplicationRolesUnchanged();

            var evidence = new
            {
                Engine = "SQL Server 2022",
                Image = IntegrationTestFixture.SqlServerImage,
                Topology = "one dedicated isolated SQL Server container",
                Revision = Assembly.GetExecutingAssembly().GetCustomAttribute<AssemblyInformationalVersionAttribute>()?.InformationalVersion ?? "unknown",
                StartedAtUtc = startedAt,
                EndedAtUtc = DateTimeOffset.UtcNow,
                Permissions = permissionEvidence,
                ExtendedEvents = sanitizedEvents.GroupBy(item => item.EventKind, StringComparer.Ordinal)
                    .ToDictionary(group => group.Key, group => group.LongCount(), StringComparer.Ordinal)
            };
            var evidenceJson = JsonSerializer.Serialize(evidence);
            AssertForbiddenValuesAbsent([evidenceJson], runId, databaseName, instanceLogin, databaseLogin, recoveryLogin, runtimeLogin, migrationLogin, eventFilePath, backupFilePath, Password);
            Console.WriteLine(evidenceJson);
        }
        finally
        {
            await RestoreAndCleanupAsync(adminConnectionString, container, databaseName, instanceLogin, databaseLogin, recoveryLogin, runtimeLogin, migrationLogin,
                sessionName, eventFilePath, backupFilePath, originalBlockedThreshold, originalShowAdvanced).ConfigureAwait(false);
        }
    }

    private static async Task AssertRealSqlCmdEscapingAsync(MsSqlContainer container, string connectionString, string runId)
    {
        var markerDatabase = $"Issue255Sqlcmd_{runId}";
        var script = await File.ReadAllBytesAsync(Path.Combine(
            FindRepositoryRoot(), "deploy", "sql", "query-store-capture.sql")).ConfigureAwait(false);
        var wrapper = Encoding.UTF8.GetBytes($"""
            #!/bin/sh
            export SQLCMDPASSWORD="$MSSQL_SA_PASSWORD"
            exec /opt/mssql-tools18/bin/sqlcmd -C -S localhost -U sa -d master -b \
              -i /tmp/issue255-query-store-capture.sql \
              -v "DatabaseName=x']; CREATE DATABASE [{markerDatabase}];--"
            """);
        await container.CopyAsync(script, "/tmp/issue255-query-store-capture.sql", UnixFileModes.UserRead).ConfigureAwait(false);
        await container.CopyAsync(wrapper, "/tmp/issue255-run-sqlcmd.sh",
            UnixFileModes.UserRead | UnixFileModes.UserExecute).ConfigureAwait(false);
        var result = await container.ExecAsync(["/tmp/issue255-run-sqlcmd.sh"]).ConfigureAwait(false);
        result.ExitCode.Should().NotBe(0);
        await using var admin = await OpenAsync(connectionString, "master").ConfigureAwait(false);
        (await ScalarAsync<int>(admin,
            $"SELECT COUNT(*) FROM sys.databases WHERE [name]=N'{markerDatabase}';").ConfigureAwait(false)).Should().Be(0);
    }

