    private static async Task InstallXeWrapperAsync(MsSqlContainer container)
    {
        var directories = await container.ExecAsync([
            "mkdir", "-p", "/tmp/issue255-toolkit/scripts", "/tmp/issue255-toolkit/deploy/sql"
        ]).ConfigureAwait(false);
        directories.ExitCode.Should().Be(0);
        var root = FindRepositoryRoot();
        var wrapper = await File.ReadAllBytesAsync(Path.Combine(FindRepositoryRoot(), "scripts", "sql-xe:create")).ConfigureAwait(false);
        await container.CopyAsync(wrapper, "/tmp/issue255-toolkit/scripts/sql-xe:create",
            UnixFileModes.UserRead | UnixFileModes.UserExecute |
            UnixFileModes.GroupRead | UnixFileModes.GroupExecute |
            UnixFileModes.OtherRead | UnixFileModes.OtherExecute).ConfigureAwait(false);
        foreach (var script in new[] { "xe-create.sql", "xe-drop.sql" })
        {
            var content = await File.ReadAllBytesAsync(Path.Combine(root, "deploy", "sql", script)).ConfigureAwait(false);
            await container.CopyAsync(content, $"/tmp/issue255-toolkit/deploy/sql/{script}",
                UnixFileModes.UserRead | UnixFileModes.GroupRead | UnixFileModes.OtherRead).ConfigureAwait(false);
        }
        var credentialSetup = Encoding.UTF8.GetBytes("""
            #!/bin/sh
            set -eu
            umask 077
            {
                printf '%s\n' "$ISSUE255_SQLCMD_USER"
                printf '%s\n' "$MSSQL_SA_PASSWORD"
            } > /tmp/issue255-sqlcmd.credentials
            """);
        await container.CopyAsync(credentialSetup, "/tmp/issue255-create-sqlcmd-credentials",
            UnixFileModes.UserRead | UnixFileModes.UserExecute |
            UnixFileModes.GroupRead | UnixFileModes.GroupExecute |
            UnixFileModes.OtherRead | UnixFileModes.OtherExecute).ConfigureAwait(false);
        var credentials = await container.ExecAsync(["/tmp/issue255-create-sqlcmd-credentials"]).ConfigureAwait(false);
        credentials.ExitCode.Should().Be(0);
        var maliciousIni = Encoding.UTF8.GetBytes("""
            CREATE EVENT SESSION [Issue255InheritedSqlcmd] ON SERVER
            ADD EVENT sqlserver.error_reported;
            GO
            RAISERROR ('Inherited SQLCMDINI executed.', 16, 1);
            GO
            """);
        await container.CopyAsync(maliciousIni, "/tmp/issue255-malicious-sqlcmd.ini",
            UnixFileModes.UserRead | UnixFileModes.GroupRead | UnixFileModes.OtherRead).ConfigureAwait(false);
        var maliciousLauncher = Encoding.UTF8.GetBytes("""
            #!/bin/sh
            set -eu
            export SQLCMDINI=/tmp/issue255-malicious-sqlcmd.ini
            export SQLCMDERRORLEVEL=25
            export SQLCMDSERVER=invalid.example
            export SQLCMDDBNAME=invalid_database
            export SQLCMDUSER=invalid_user
            export SQLCMDPASSWORD=invalid_password
            export SQLCMDLOGINTIMEOUT=1
            export SQLCMDSTATTIMEOUT=1
            export SQLCMDPACKETSIZE=512
            export SQLCMDHEADERS=0
            export SQLCMDCOLSEP='|'
            exec /tmp/issue255-toolkit/scripts/sql-xe:create "$@"
            """);
        await container.CopyAsync(maliciousLauncher, "/tmp/issue255-malicious-sqlcmd-environment",
            UnixFileModes.UserRead | UnixFileModes.UserExecute |
            UnixFileModes.GroupRead | UnixFileModes.GroupExecute |
            UnixFileModes.OtherRead | UnixFileModes.OtherExecute).ConfigureAwait(false);
    }

    private static async Task<bool> RunXeWrapperPreflightAsync(MsSqlContainer container, string runId, SafeStage? stage = null)
    {
        var result = await container.ExecAsync([
            "/tmp/issue255-toolkit/scripts/sql-xe:create",
            "--root", EventRootDirectory,
            "--root-owner", "mssql",
            "--service-user", "mssql",
            "--run-id", runId,
            "--preflight-only"
        ]).ConfigureAwait(false);
        if (result.ExitCode == 0) result.Stdout.Trim().Should().Be("xe-preflight-created");
        else if (stage is not null)
        {
            stage.Value += result.Stderr switch
            {
                var value when value.Contains("canonical", StringComparison.Ordinal) => "-canonical-root",
                var value when value.Contains("owner", StringComparison.Ordinal) => "-root-owner",
                var value when value.Contains("writable", StringComparison.Ordinal) => "-root-mode",
                var value when value.Contains("traverse", StringComparison.Ordinal) => "-service-access",
                var value when value.Contains("lock", StringComparison.Ordinal) => "-lock",
                var value when value.Contains("already exists", StringComparison.Ordinal) => "-existing-run",
                var value when value.Contains("post-creation", StringComparison.Ordinal) => "-created-directory",
                var value when value.Contains("prefix", StringComparison.Ordinal) => "-prefix",
                var value when value.Contains("root or", StringComparison.Ordinal) => "-wrapper-identity",
                var value when value.Contains("Usage", StringComparison.Ordinal) => "-usage",
                var value when value.Contains("command not found", StringComparison.Ordinal) => "-missing-command",
                var value when value.Contains("Permission denied", StringComparison.Ordinal) => "-permission",
                var value when value.Contains("invalid", StringComparison.OrdinalIgnoreCase) => "-invalid-command-input",
                _ => "-unclassified"
            };
        }
        return result.ExitCode == 0;
    }

