    private static async Task<int> QueryStoreOwnerCountAsync(SqlConnection connection, string? token = null)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = token is null
            ? "SELECT COUNT(*) FROM sys.extended_properties WHERE [class]=0 AND [name]=N'HvoSqlOps_QueryStoreOwner';"
            : "SELECT COUNT(*) FROM sys.extended_properties WHERE [class]=0 AND [name]=N'HvoSqlOps_QueryStoreOwner' AND CONVERT(varchar(32), [value])=@token;";
        if (token is not null)
            _ = command.Parameters.Add(new SqlParameter("@token", SqlDbType.VarChar, 32) { Value = token });
        return Convert.ToInt32(await command.ExecuteScalarAsync().ConfigureAwait(false), CultureInfo.InvariantCulture);
    }

