    private static async Task ProduceBlockedWriterAsync(string connectionString, string databaseName)
    {
        var attributed = WithApplication(connectionString, databaseName, "HVO.SkyMonitor.LogicHost.Runtime");
        await using var blocker = new SqlConnection(attributed);
        await using var waiter = new SqlConnection(attributed);
        await blocker.OpenAsync().ConfigureAwait(false);
        await waiter.OpenAsync().ConfigureAwait(false);
        await using var transaction = (SqlTransaction)await blocker.BeginTransactionAsync().ConfigureAwait(false);
        await NonQueryAsync(blocker, "UPDATE dbo.Issue255Invariant SET Quantity=Quantity WHERE Id=1;", transaction).ConfigureAwait(false);
        var waiting = NonQueryAsync(waiter, "UPDATE dbo.Issue255Invariant SET Quantity=Quantity WHERE Id=1;", timeout: 25);
        await Task.Delay(TimeSpan.FromSeconds(17)).ConfigureAwait(false);
        await transaction.RollbackAsync().ConfigureAwait(false);
        await waiting.WaitAsync(TimeSpan.FromSeconds(10)).ConfigureAwait(false);
    }

    private static async Task<int> ProduceMixedDeadlockAsync(string connectionString, string databaseName)
    {
        await using var first = new SqlConnection(WithApplication(connectionString, databaseName, "HVO.SkyMonitor.LogicHost.Runtime"));
        await using var second = new SqlConnection(WithApplication(connectionString, databaseName, "HVO.SkyMonitor.LogicHost.Migration"));
        await first.OpenAsync().ConfigureAwait(false);
        await second.OpenAsync().ConfigureAwait(false);
        await using var firstTransaction = (SqlTransaction)await first.BeginTransactionAsync().ConfigureAwait(false);
        await using var secondTransaction = (SqlTransaction)await second.BeginTransactionAsync().ConfigureAwait(false);
        await NonQueryAsync(first, "UPDATE dbo.Issue255Invariant SET Quantity=Quantity WHERE Id=1;", firstTransaction).ConfigureAwait(false);
        await NonQueryAsync(second, "UPDATE dbo.Issue255Invariant SET Quantity=Quantity WHERE Id=2;", secondTransaction).ConfigureAwait(false);
        var firstWait = CaptureSqlNumberAsync(first, "UPDATE dbo.Issue255Invariant SET Quantity=Quantity WHERE Id=2;", firstTransaction);
        await Task.Delay(100).ConfigureAwait(false);
        var secondWait = CaptureSqlNumberAsync(second, "UPDATE dbo.Issue255Invariant SET Quantity=Quantity WHERE Id=1;", secondTransaction);
        var results = await Task.WhenAll(firstWait, secondWait).WaitAsync(TimeSpan.FromSeconds(20)).ConfigureAwait(false);
        results.Count(number => number == 1205).Should().Be(1);
        return 1205;
    }

    private static async Task<int?> CaptureSqlNumberAsync(SqlConnection connection, string text, SqlTransaction transaction)
    {
        try
        {
            await NonQueryAsync(connection, text, transaction, 15).ConfigureAwait(false);
            return null;
        }
        catch (SqlException exception)
        {
            return exception.Number;
        }
    }

    private static async Task<IReadOnlyList<string>> ReadRawEventsAsync(string connectionString, string eventFilePath)
    {
