        {
            await using var connection = await OpenAsync(connectionString, "master").ConfigureAwait(false);
            await using var command = connection.CreateCommand();
            command.CommandText = "SELECT CONVERT(nvarchar(max), [event_data]) FROM sys.fn_xe_file_target_read_file(@path, NULL, NULL, NULL);";
            _ = command.Parameters.Add(new SqlParameter("@path", SqlDbType.NVarChar, 4000) { Value = eventFilePath + "*.xel" });
