        }
    }

    private static SanitizedEvent? SanitizeEvent(string rawXml)
    {
        try
        {
            var root = XDocument.Parse(rawXml, LoadOptions.None).Root
                ?? throw new InvalidOperationException();
            var kind = (string?)root.Attribute("name") switch
            {
                "blocked_process_report" => "blocked-process",
                "xml_deadlock_report" => "deadlock",
                _ => null
            };
            if (kind is null) return null;
            var participants = root.Descendants("process")
                .Select(process => MapApplication((string?)process.Attribute("clientapp")))
                .Distinct(StringComparer.Ordinal)
                .OrderBy(ParticipantOrder)
                .ToArray();
            var approvedCount = participants.Count(item => item != "other");
            var attribution = participants.Contains("other", StringComparer.Ordinal) && approvedCount > 0
                ? "mixed-approved-other"
                : approvedCount > 1
                    ? "mixed-approved"
                    : participants.SingleOrDefault() ?? "other";
            var observedAt = DateTimeOffset.Parse((string?)root.Attribute("timestamp") ?? throw new InvalidOperationException(),
                CultureInfo.InvariantCulture, DateTimeStyles.AssumeUniversal | DateTimeStyles.AdjustToUniversal);
            return new(kind, attribution, string.Join('+', participants), observedAt);
        }
        catch
        {
            throw new AssertFailedException("Restricted in-memory Extended Events parsing failed without retaining raw XML.");
        }
    }

    private static string MapApplication(string? application) => application switch
    {
        "HVO.SkyMonitor.LogicHost.Runtime" => "logichost-runtime",
        "HVO.SkyMonitor.LogicHost.Migration" => "logichost-migration",
        "HVO.SkyMonitor.LogicHost.ObjectLock" => "logichost-object-lock",
        _ => "other"
    };

    private static int ParticipantOrder(string participant) => participant switch
    {
        "logichost-runtime" => 0,
        "logichost-migration" => 1,
        "logichost-object-lock" => 2,
        _ => 3
    };

    private static async Task<ScriptResult> ExecuteScriptAsync(SqlConnection connection, string fileName, IReadOnlyDictionary<string, string> variables)
    {
        var path = Path.Combine(FindRepositoryRoot(), "deploy", "sql", fileName);
        var script = await File.ReadAllTextAsync(path).ConfigureAwait(false);
        foreach (var variable in variables)
        {
            script = script.Replace($"$(ESCAPE_SQUOTE({variable.Key}))",
                variable.Value.Replace("'", "''", StringComparison.Ordinal), StringComparison.Ordinal);
            script = script.Replace($"$({variable.Key})", variable.Value, StringComparison.Ordinal);
        }
        if (script.Contains("$(", StringComparison.Ordinal))
            throw new AssertFailedException("A shipped SQL script has an unresolved SQLCMD variable.");

        try
        {
            await using var command = connection.CreateCommand();
            command.CommandText = script;
            command.CommandTimeout = 180;
            var resultSets = new List<ScriptResultSet>();
            await using var reader = await command.ExecuteReaderAsync().ConfigureAwait(false);
            do
            {
                if (reader.FieldCount == 0) continue;
                var columns = Enumerable.Range(0, reader.FieldCount).Select(reader.GetName).ToArray();
                var rows = new List<IReadOnlyDictionary<string, object?>>();
                while (await reader.ReadAsync().ConfigureAwait(false))
                {
                    var row = new Dictionary<string, object?>(StringComparer.Ordinal);
                    for (var index = 0; index < reader.FieldCount; index++)
                        row.Add(columns[index], await reader.IsDBNullAsync(index).ConfigureAwait(false) ? null : reader.GetValue(index));
                    rows.Add(row);
                }
                resultSets.Add(new(columns, rows));
            } while (await reader.NextResultAsync().ConfigureAwait(false));
            return new(resultSets);
        }
        catch (SqlException exception)
        {
            throw new SanitizedScriptException(fileName, exception.Number);
        }
    }

    private static async Task<SanitizedScriptException> CaptureSanitizedScriptFailureAsync(Func<Task<ScriptResult>> action)
    {
        try
        {
            _ = await action().ConfigureAwait(false);
            throw new AssertFailedException("The shipped SQL script unexpectedly succeeded.");
        }
        catch (SanitizedScriptException exception)
        {
            return exception;
        }
    }

    private static void AssertFailureIsSanitized(Exception exception, params string[] forbidden)
    {
        var rendered = exception.ToString();
        foreach (var value in forbidden)
            if (rendered.Contains(value, StringComparison.OrdinalIgnoreCase))
                Assert.Fail("A sanitized script failure retained a forbidden value.");
    }

    private static ScriptResultSet RequireResultSet(ScriptResult result, int index, params string[] columns)
    {
        result.ResultSets.Count.Should().BeGreaterThan(index);
        var set = result.ResultSets[index];
        set.Columns.Should().Equal(columns);
        return set;
    }

    private static IReadOnlyDictionary<string, object?> RequireSingleRow(ScriptResult result, int index, params string[] columns)
    {
        var set = RequireResultSet(result, index, columns);
        set.Rows.Should().ContainSingle();
        return set.Rows[0];
    }

    private static string RequireText(IReadOnlyDictionary<string, object?> row, string column) =>
        Convert.ToString(row[column], CultureInfo.InvariantCulture) ?? throw new AssertFailedException($"Sanitized column {column} is null.");

    private static long RequireInt64(IReadOnlyDictionary<string, object?> row, string column) =>
        Convert.ToInt64(row[column], CultureInfo.InvariantCulture);

    private static decimal RequireDecimal(IReadOnlyDictionary<string, object?> row, string column) =>
        Convert.ToDecimal(row[column], CultureInfo.InvariantCulture);

    private static void ValidateCapacity(ScriptResult result)
    {
        result.ResultSets.Should().HaveCount(15);
        var metadata = RequireResultSet(result, 0, "area", "scope", "attribution", "metric", "value", "unit", "observed_at_utc");
        metadata.Rows.Should().HaveCount(2);
        metadata.Rows.All(row => RequireText(row, "scope") == "instance").Should().BeTrue();
        metadata.Rows.Any(row => RequireText(row, "metric") == "engine-major-version" && RequireDecimal(row, "value") == 16).Should().BeTrue();
        var cpu = RequireSingleRow(result, 1, "area", "scope", "attribution", "logical_cpu_count", "scheduler_count", "sql_process_kernel_time_ms", "sql_process_user_time_ms", "observed_at_utc");
        RequireText(cpu, "scope").Should().Be("instance-wide-shared");
        RequireInt64(cpu, "logical_cpu_count").Should().BePositive();
        var physical = RequireSingleRow(result, 2, "area", "scope", "attribution", "total_bytes", "used_bytes", "free_bytes", "headroom_bytes", "observed_at_utc");
        RequireInt64(physical, "total_bytes").Should().BePositive();
        RequireInt64(physical, "free_bytes").Should().BeGreaterThanOrEqualTo(0);
        RequireInt64(physical, "total_bytes").Should().Be(RequireInt64(physical, "used_bytes") + RequireInt64(physical, "free_bytes"));
        RequireInt64(physical, "headroom_bytes").Should().Be(RequireInt64(physical, "free_bytes"));
        RequireSingleRow(result, 3, "area", "scope", "attribution", "physical_used_bytes", "virtual_committed_bytes", "virtual_free_bytes", "memory_utilization_percent", "page_fault_count", "observed_at_utc");
        var configured = RequireSingleRow(result, 4, "area", "scope", "attribution", "configured_min_bytes", "configured_max_bytes", "committed_bytes", "target_bytes", "target_headroom_bytes", "observed_at_utc");
        RequireInt64(configured, "configured_max_bytes").Should().BePositive();
        RequireResultSet(result, 5, "area", "scope", "attribution", "session_count", "active_request_count", "open_transaction_session_count", "blocked_request_count", "requested_grant_kb", "granted_memory_kb", "lock_session_count", "observed_at_utc").Rows.Should().NotBeEmpty();
        RequireResultSet(result, 6, "area", "scope", "attribution", "metric", "sample_count", "value_ms", "signal_value_ms", "observed_at_utc").Rows.Should().NotBeEmpty();
        var workers = RequireSingleRow(result, 7, "area", "scope", "attribution", "current_workers", "active_workers", "runnable_tasks", "current_tasks", "effective_max_workers", "configured_max_worker_threads", "worker_headroom", "observed_at_utc");
        RequireInt64(workers, "effective_max_workers").Should().BePositive();
        RequireInt64(workers, "worker_headroom").Should().BeGreaterThanOrEqualTo(0);
        var grants = RequireSingleRow(result, 8, "area", "scope", "attribution", "grant_count", "requested_kb", "granted_kb", "waiting_grant_count", "observed_at_utc");
        RequireInt64(grants, "requested_kb").Should().BeGreaterThanOrEqualTo(0);
        RequireInt64(grants, "granted_kb").Should().BeGreaterThanOrEqualTo(0);
        RequireInt64(grants, "waiting_grant_count").Should().BeGreaterThanOrEqualTo(0);
        var spills = RequireSingleRow(result, 9, "area", "scope", "attribution", "spill_pages", "observed_at_utc");
        RequireInt64(spills, "spill_pages").Should().BeGreaterThanOrEqualTo(0);
        var tempdb = RequireSingleRow(result, 10, "area", "scope", "attribution", "allocated_file_bytes", "used_file_bytes", "free_file_bytes", "headroom_bytes", "version_store_bytes", "observed_at_utc");
        RequireInt64(tempdb, "allocated_file_bytes").Should().BePositive();
        RequireInt64(tempdb, "allocated_file_bytes").Should().Be(RequireInt64(tempdb, "used_file_bytes") + RequireInt64(tempdb, "free_file_bytes"));
        RequireResultSet(result, 11, "area", "scope", "attribution", "file_kind", "allocated_bytes", "bytes_read", "bytes_written", "read_count", "write_count", "read_stall_ms", "write_stall_ms", "percent_growth_file_count", "fixed_size_file_count", "observed_at_utc").Rows.Should().HaveCount(2);
        var volumes = RequireSingleRow(result, 12, "area", "scope", "attribution", "volume_count", "total_bytes", "used_bytes", "free_bytes", "headroom_bytes", "observed_at_utc");
        RequireText(volumes, "scope").Should().Be("target-database-volumes-shared");
        RequireInt64(volumes, "volume_count").Should().BePositive();
        RequireInt64(volumes, "total_bytes").Should().Be(RequireInt64(volumes, "used_bytes") + RequireInt64(volumes, "free_bytes"));
        var log = RequireSingleRow(result, 13, "area", "scope", "attribution", "allocated_bytes", "used_bytes", "free_bytes", "headroom_bytes", "bytes_since_log_backup", "reuse_wait", "observed_at_utc");
        RequireInt64(log, "allocated_bytes").Should().Be(RequireInt64(log, "used_bytes") + RequireInt64(log, "free_bytes"));
        RequireSingleRow(result, 14, "area", "scope", "attribution", "state", "event_count", "first_observed_server_local", "last_observed_server_local");
    }

