        RequireInt64(indexes, "page_count").Should().BeGreaterThanOrEqualTo(0);
    }

    private static void AddOutput(List<string> output, ScriptResult result) => output.Add(JsonSerializer.Serialize(result.ResultSets));

    private static async Task RecordPermissionAsync(SqlConnection connection, ICollection<PermissionEvidence> evidence, string permission, bool expected, string scope = "SERVER")
    {
        await using var command = connection.CreateCommand();
        command.CommandText = scope == "SERVER"
            ? "SELECT HAS_PERMS_BY_NAME(NULL, NULL, @permission);"
            : "SELECT HAS_PERMS_BY_NAME(DB_NAME(), N'DATABASE', @permission);";
        _ = command.Parameters.Add(new SqlParameter("@permission", SqlDbType.NVarChar, 128) { Value = permission });
        var passed = Convert.ToInt32(await command.ExecuteScalarAsync().ConfigureAwait(false), CultureInfo.InvariantCulture) == 1;
        passed.Should().Be(expected);
        evidence.Add(new(permission, scope, expected ? "pass" : "denied-as-required"));
    }

    private static async Task RecordServerRoleMembershipAsync(
        SqlConnection connection,
        ICollection<PermissionEvidence> evidence,
        string role)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = "SELECT IS_SRVROLEMEMBER(@role);";
        _ = command.Parameters.Add(new SqlParameter("@role", SqlDbType.NVarChar, 128) { Value = role });
        Convert.ToInt32(await command.ExecuteScalarAsync().ConfigureAwait(false), CultureInfo.InvariantCulture).Should().Be(1);
        evidence.Add(new("membership", "EPHEMERAL RECOVERY ROLE", "pass"));
    }

    private static void AssertForbiddenValuesAbsent(IEnumerable<string> output, params string[] forbidden)
    {
        var serialized = string.Join('\n', output);
        foreach (var value in forbidden.Where(value => !string.IsNullOrEmpty(value)))
            serialized.Contains(value, StringComparison.OrdinalIgnoreCase).Should().BeFalse();
    }

    private static void AssertApplicationRolesUnchanged()
    {
        var root = FindRepositoryRoot();
        var roleSql = File.ReadAllText(Path.Combine(root, "deploy", "sql", "logichost-runtime-role.sql")) +
            File.ReadAllText(Path.Combine(root, "deploy", "sql", "logichost-migration-role.sql"));
        foreach (var permission in new[]
                 {
                     "VIEW SERVER PERFORMANCE STATE", "VIEW DATABASE PERFORMANCE STATE", "ALTER ANY EVENT SESSION",
                     "ALTER TRACE", "ALTER SETTINGS", "BACKUP DATABASE", "CREATE ANY DATABASE"
                 })
            roleSql.Contains(permission, StringComparison.OrdinalIgnoreCase).Should().BeFalse();
    }

    private static async Task DeleteExactFilesAsync(MsSqlContainer container, string eventFilePath, string backupFilePath)
    {
        var eventDirectory = eventFilePath[..eventFilePath.LastIndexOf('/')];
        var result = await container.ExecAsync(["/bin/sh", "-c",
            $"rm -f -- '{eventFilePath}'*.xel '{backupFilePath}' && if test -d '{eventDirectory}'; then rmdir -- '{eventDirectory}'; fi && " +
            $"if test -d '{EventRootDirectory}'; then rm -f -- '{EventRootDirectory}/.hvo-xe-create.lock' && rmdir -- '{EventRootDirectory}'; fi"]).ConfigureAwait(false);
        if (result.ExitCode != 0) throw new InvalidOperationException("Exact run-owned file cleanup failed.");
    }

    private static async Task AssertExactCleanupAsync(string connectionString, MsSqlContainer container, string databaseName, string sessionName, string eventFilePath, string backupFilePath)
    {
        await using var admin = await OpenAsync(connectionString, "master").ConfigureAwait(false);
        (await ScalarAsync<int>(admin, $"SELECT COUNT(*) FROM sys.server_event_sessions WHERE [name]=N'{sessionName}';").ConfigureAwait(false)).Should().Be(0);
        (await ScalarAsync<int>(admin, $"SELECT COUNT(*) FROM sys.databases WHERE [name]=N'HvoVerify_{sessionName[10..]}';").ConfigureAwait(false)).Should().Be(0);
        (await ScalarAsync<int>(admin, $"SELECT COUNT(*) FROM sys.databases WHERE [name]=N'{databaseName}';").ConfigureAwait(false)).Should().Be(1);
        var runId = sessionName[10..];
        var eventDirectory = eventFilePath[..eventFilePath.LastIndexOf('/')];
        var files = await container.ExecAsync(["/bin/sh", "-c", $"if test -e '{eventDirectory}' || test -e '{EventRootDirectory}' || ls '{eventFilePath}'*.xel '{backupFilePath}' '/var/opt/mssql/data/HvoVerify_{runId}_'* >/dev/null 2>&1; then exit 1; fi"]).ConfigureAwait(false);
        files.ExitCode.Should().Be(0);
    }

    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1031:Do not catch general exception types",
        Justification = "Cleanup must aggregate independent server-setting, SQL-artifact, and file failures without skipping later restoration steps.")]
    private static async Task RestoreAndCleanupAsync(
        string connectionString,
        MsSqlContainer container,
        string databaseName,
        string instanceLogin,
        string databaseLogin,
        string recoveryLogin,
        string runtimeLogin,
        string migrationLogin,
        string sessionName,
        string eventFilePath,
        string backupFilePath,
        int blockedThreshold,
        int showAdvanced)
    {
        var failures = new List<Exception>();
        foreach (var setting in new[]
                 {
                     (Name: "blocked process threshold (s)", Value: blockedThreshold),
                     (Name: "show advanced options", Value: showAdvanced)
                 })
        {
            try
            {
                await using var admin = await OpenAsync(connectionString, "master").ConfigureAwait(false);
                await NonQueryAsync(admin, $"EXEC sys.sp_configure N'{setting.Name}', {setting.Value}; RECONFIGURE;").ConfigureAwait(false);
                var restored = await ScalarAsync<int>(admin,
                    $"SELECT CONVERT(int, [value_in_use]) FROM sys.configurations WHERE [name]=N'{setting.Name}';").ConfigureAwait(false);
                if (restored != setting.Value)
                    failures.Add(new InvalidOperationException("One server setting failed restoration verification."));
            }
            catch
            {
                failures.Add(new InvalidOperationException("One server setting restoration operation failed."));
            }
        }

        try
        {
            await using var admin = await OpenAsync(connectionString, "master").ConfigureAwait(false);
            await NonQueryAsync(admin, $"""
                IF EXISTS (SELECT 1 FROM sys.dm_xe_sessions WHERE [name]=N'{sessionName}') ALTER EVENT SESSION [{sessionName}] ON SERVER STATE=STOP;
                IF EXISTS (SELECT 1 FROM sys.server_event_sessions WHERE [name]=N'{sessionName}') DROP EVENT SESSION [{sessionName}] ON SERVER;
                IF DB_ID(N'HvoVerify_{sessionName[10..]}') IS NOT NULL
                BEGIN
                    ALTER DATABASE [HvoVerify_{sessionName[10..]}] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
                    DROP DATABASE [HvoVerify_{sessionName[10..]}];
                END;
                IF DB_ID(N'{databaseName}') IS NOT NULL
                BEGIN
                    ALTER DATABASE [{databaseName}] SET SINGLE_USER WITH ROLLBACK IMMEDIATE;
                    DROP DATABASE [{databaseName}];
                END;
                DECLARE @kill nvarchar(max);
                SELECT @kill=STRING_AGG(CONVERT(nvarchar(max), N'KILL ' + CONVERT(nvarchar(11), [session_id]) + N';'), N'')
                FROM sys.dm_exec_sessions WHERE [login_name] IN (N'{instanceLogin}', N'{databaseLogin}', N'{recoveryLogin}', N'{runtimeLogin}', N'{migrationLogin}') AND [session_id]<>@@SPID;
                IF @kill IS NOT NULL EXEC sys.sp_executesql @kill;
                IF SUSER_ID(N'{instanceLogin}') IS NOT NULL DROP LOGIN [{instanceLogin}];
                IF SUSER_ID(N'{databaseLogin}') IS NOT NULL DROP LOGIN [{databaseLogin}];
                IF SUSER_ID(N'{recoveryLogin}') IS NOT NULL DROP LOGIN [{recoveryLogin}];
                IF SUSER_ID(N'{runtimeLogin}') IS NOT NULL DROP LOGIN [{runtimeLogin}];
                IF SUSER_ID(N'{migrationLogin}') IS NOT NULL DROP LOGIN [{migrationLogin}];
                """).ConfigureAwait(false);
        }
        catch
        {
            failures.Add(new InvalidOperationException("Run-owned SQL cleanup failed."));
        }

        try
        {
            await DeleteExactFilesAsync(container, eventFilePath, backupFilePath).ConfigureAwait(false);
            var files = await container.ExecAsync(["/bin/sh", "-c", $"if ls '{eventFilePath}'*.xel '{backupFilePath}' >/dev/null 2>&1; then exit 1; fi"]).ConfigureAwait(false);
            if (files.ExitCode != 0) failures.Add(new InvalidOperationException("Run-owned file cleanup verification failed."));
        }
        catch
        {
            failures.Add(new InvalidOperationException("Run-owned file cleanup failed."));
        }

        if (failures.Count > 0) throw new AggregateException("Issue 255 cleanup had sanitized failures.", failures);
    }

    private static string CreatePrincipalConnectionString(string connectionString, string login) =>
        new SqlConnectionStringBuilder(connectionString)
        {
            UserID = login,
            Password = Password,
            IntegratedSecurity = false,
            TrustServerCertificate = true,
            ApplicationName = "HVO.SkyMonitor.LogicHost.Runtime"
        }.ConnectionString;

    private static string WithApplication(string connectionString, string database, string application) =>
        new SqlConnectionStringBuilder(connectionString) { InitialCatalog = database, ApplicationName = application }.ConnectionString;

    private static async Task<SqlConnection> OpenAsync(string connectionString, string database)
    {
        var connection = new SqlConnection(new SqlConnectionStringBuilder(connectionString) { InitialCatalog = database }.ConnectionString);
        await connection.OpenAsync().ConfigureAwait(false);
        return connection;
    }

    private static async Task NonQueryAsync(SqlConnection connection, string text, SqlTransaction? transaction = null, int timeout = 60)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = text;
        command.Transaction = transaction;
        command.CommandTimeout = timeout;
        _ = await command.ExecuteNonQueryAsync().ConfigureAwait(false);
    }

    private static async Task<T> ScalarAsync<T>(SqlConnection connection, string text)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = text;
        var value = await command.ExecuteScalarAsync().ConfigureAwait(false)
            ?? throw new InvalidOperationException("The scalar probe returned null.");
        return (T)Convert.ChangeType(value, typeof(T), CultureInfo.InvariantCulture);
    }

    private static async Task<IReadOnlyList<string>> ReadStringsAsync(SqlConnection connection, string text)
    {
        await using var command = connection.CreateCommand();
        command.CommandText = text;
        var values = new List<string>();
        await using var reader = await command.ExecuteReaderAsync().ConfigureAwait(false);
        while (await reader.ReadAsync().ConfigureAwait(false)) values.Add(reader.GetString(0));
        return values;
    }

    private static string FindRepositoryRoot()
    {
        for (var directory = new DirectoryInfo(AppContext.BaseDirectory); directory is not null; directory = directory.Parent)
            if (File.Exists(Path.Combine(directory.FullName, "HVO.SkyMonitor.v9.slnx"))) return directory.FullName;
        throw new InvalidOperationException("The repository root could not be found.");
    }

    private sealed record ScriptResult(IReadOnlyList<ScriptResultSet> ResultSets);
    private sealed record ScriptResultSet(IReadOnlyList<string> Columns, IReadOnlyList<IReadOnlyDictionary<string, object?>> Rows);
    private sealed record PermissionEvidence(string Permission, string Scope, string Result);
    private sealed record XeWrapperResult(long ExitCode, string StandardOutput, string StandardError);
    private sealed record SanitizedEvent(string EventKind, string Attribution, string ParticipantSet, DateTimeOffset ObservedAtUtc);
    private sealed class SafeStage(string value) { internal string Value { get; set; } = value; }

    [System.Diagnostics.CodeAnalysis.SuppressMessage("Design", "CA1032:Implement standard exception constructors",
        Justification = "The test-only exception deliberately accepts only a safe script basename and SQL error number.")]
    private sealed class SanitizedScriptException(string scriptName, int sqlErrorNumber)
        : Exception($"SQL operator script '{Path.GetFileName(scriptName)}' failed with SQL error {sqlErrorNumber}.")
    {
        internal int SqlErrorNumber { get; } = sqlErrorNumber;
    }
